    for integer, description in AdditionalConditions.CONDITION_DESCRIPTION.items():
        allowed_values += ' - {:d} for "{}"\n'.format(integer, description)

    def __new__(cls, integer):
        """#TODO: Missing doc"""
        if str(int(integer)) != str(integer):
            raise ValueError(
