def get_site_coordination_environment(
    self,
    site,
    isite=None,
    dequivsite=None,
    dthissite=None,
    mysym=None,
    return_map=False,
):
    """
    #TODO: Missing doc
    :param site:
    :param isite:
    :param dequivsite:
    :param dthissite:
    :param mysym:
    :param return_map:
    :return:
    """
    if isite is None:
        [
            isite,
            dequivsite,
            dthissite,
            mysym,
        ] = self.equivalent_site_index_and_transform(site)
    neighbors_normalized_distances = self.structure_environments.voronoi.neighbors_normalized_distances[
        isite
    ]
    neighbors_normalized_angles = self.structure_environments.voronoi.neighbors_normalized_angles[
        isite
    ]
    idist = None
    for iwd, wd in enumerate(neighbors_normalized_distances):
        if self.distance_cutoff >= wd["min"]:
            idist = iwd
        else:
            break
    iang = None
    for iwa, wa in enumerate(neighbors_normalized_angles):
        if self.angle_cutoff <= wa["max"]:
            iang = iwa
        else:
            break
    if idist is None or iang is None:
        raise ValueError("Distance or angle parameter not found ...")

    my_cn = None
    my_inb_set = None
    found = False
    for cn, nb_sets in self.structure_environments.neighbors_sets[isite].items():
        for inb_set, nb_set in enumerate(nb_sets):
            sources = [
                src
                for src in nb_set.sources
                if src["origin"] == "dist_ang_ac_voronoi"
                and src["ac"] == self.additional_condition
            ]
            for src in sources:
                if src["idp"] == idist and src["iap"] == iang:
                    my_cn = cn
                    my_inb_set = inb_set
                    found = True
                    break
            if found:
                break
        if found:
            break

    if not found:
        return None

    cn_map = (my_cn, my_inb_set)
    ce = self.structure_environments.ce_list[
        self.structure_environments.sites_map[isite]
    ][cn_map[0]][cn_map[1]]
    if ce is None:
        return None
    coord_geoms = ce.coord_geoms
    if return_map:
        if coord_geoms is None:
            return cn_map[0], cn_map
        return (
            ce.minimum_geometry(symmetry_measure_type=self._symmetry_measure_type),
            cn_map,
        )
    if coord_geoms is None:
        return cn_map[0]
    return ce.minimum_geometry(
        symmetry_measure_type=self._symmetry_measure_type
    )
